            "이 약의 주성분은 클로르헥시딘글루콘산염(Chlorhexidine Gluconate)이에요. 클로르헥시딘은 구강 분야에서 가장 널리 사용되는 항균 소독제로, '구강 항균의 골드 스탠다드'라고 불리기도 해요. 세균의 세포막을 파괴해서 구강 내 유해 세균을 효과적으로 제거해줘요.\n\n클로르헥시딘의 가장 큰 장점은 '잔류 항균 효과(substantivity)'예요. 한 번 바르면 구강 점막과 치아 표면에 흡착되어 수시간 동안 항균 효과가 지속돼요. 단순히 세균을 죽이는 것뿐만 아니라 새로운 세균이 붙는 것도 막아주는 거예요. 그래서 잇몸 수술이나 스케일링 후 감염 예방에도 많이 사용돼요.\n\n첨가제로 폴리에틸렌글리콜(PEG)이 연고 기제로 사용돼요. PEG는 수용성 기제라서 구강의 습한 환경에서도 잘 녹아 흡수되고, 사용 후 물로 쉽게 씻어낼 수 있어요. 점막 자극이 적어서 구강용 연고 기제로 많이 쓰이는 성분이에요.",
