          "면봉 같은 도구에 알보큐액을 적셔 헐거나 부은 부위에 여러 번 반복해서 발라주는 게 구강용 사용법이죠. 식약처 허가사항엔 정해진 하루 횟수가 따로 표기돼 있지 않아요. 증상 부위에 국소적으로 반복 도포하면 돼요.\n\n바른 뒤엔 입안을 물로 충분히 헹궈야 해요. 강한 산성이라 그대로 두면 치아 법랑질이 상할 수 있어요. 절대 삼키면 안 돼요. 눈에 들어가면 즉시 깨끗한 물로 씻어내고 병원을 찾아야 해요. 다른 외용제와 함께 바르지 않는 것도 지켜야 할 원칙이죠. 며칠 발라도 헐고 붓는 게 가라앉지 않으면 치과나 약사와 다시 상담해보는 게 좋아요. 면봉 하나로 여러 부위를 옮겨 바르기보다는 부위마다 새 면봉을 쓰는 편이 위생적이에요. 사용 후엔 도구를 소독하거나 깨끗한 물에 담가 보관하는 게 좋아요.",
