          "성인 기준으로 1회 1포를 1일 3회, 식전이나 식간에 복용하는 게 기본 복용법이에요. 식간은 밥 먹는 시간과 시간 사이, 즉 공복에 가까운 때를 말해요. 하루 총 3포죠.\n\n정해진 양보다 많이 먹는다고 효과가 빨리 오는 게 아니에요. 용법·용량은 꼭 지켜야 해요. 특히 1주 이상 계속 복용하는 건 권장되지 않아요. 그 이상 필요하면 의사나 한의사, 약사와 상의해야 하고요. 며칠 먹어도 증상이 그대로라면 복용을 멈추고 상담받아야 해요. 고령자는 대사 기능이 떨어져 있을 수 있어 필요하면 양을 줄이는 방향으로 조정해야 해요. 위장이 약한 편이라면 식욕부진이나 속불편감 같은 반응이 없는지도 함께 살펴야 하거든요.",
